import { Box } from "@/shared/ui/layout/Box";

export function ToolChip({
  label = "git", onRemove = () => {},
}: { label?: string; onRemove?: () => void }) {
  return (
    <Box as="span" className="mono" style={{
      display: "inline-flex", alignItems: "center", gap: 4,
      padding: "2px 8px", background: "var(--bg-elev)", border: "1px solid var(--border-soft)", borderRadius: 4,
      fontSize: 10.5, color: "var(--fg-muted)",
    }}>
      {label}
      <Box as="span" onClick={onRemove} style={{ cursor: "pointer", lineHeight: 1, color: "var(--fg-dim)" }}>x</Box>
    </Box>
  );
}
